(4822877, 698527, 15711, '<td valign="top">Really pretty but a bit busy, compositionally.</td>', 'Really pretty but a bit busy, compositionally.', '2008-07-14 01:03:25.000000', NULL, 1),
(4822880, 698665, 15711, '<td valign="top">Love the fly but that blob of black behind him is a bit distracting.</td>', 'Love the fly but that blob of black behind him is a bit distracting.', '2008-07-14 01:03:53.000000', NULL, 1),
(4822881, 698889, 15711, '<td valign="top">I would have her more forward but that''s just me.</td>', 'I would have her more forward but that''s just me.', '2008-07-14 01:04:26.000000', NULL, 1),
(4822889, 698475, 15711, '<td valign="top">Love the airy feel of it and the wind in her hair, but honestly the harsh black and the idea of the binoculars doesn''t match the rest of the image to me.  Great editing though.</td>', 'Love the airy feel of it and the wind in her hair, but honestly the harsh black and the idea of the binoculars doesn''t match the rest of the image to me.  Great editing though.', '2008-07-14 01:05:39.000000', NULL, 1),
(4822897, 696997, 15711, '<td valign="top">Stunning composition. I love the cool lavender and gray green with the pop of orange from the butterfly.  I wonder if the blour of the flowers in the foreground are just a bit distracting. :~)</td>', 'Stunning composition. I love the cool lavender and gray green with the pop of orange from the butterfly.  I wonder if the blour of the flowers in the foreground are just a bit distracting. :~)', '2008-07-14 01:06:36.000000', NULL, 1),
