(4825679, 698501, 94239, '<td valign="top">Beautiful shot. I love the soft tone and the way it has been cropped. 7</td>', 'Beautiful shot. I love the soft tone and the way it has been cropped. 7', '2008-07-15 06:41:42.000000', NULL, 1),
(4825681, 698735, 49109, '<td valign="top">quite overdone subject, but lovely due to its very good execution. perfect focus, centered comp works well in the square crop, border is just subtle enough. yellows are a tad oversaturated and produce slight banding. bumping up to 8</td>', 'quite overdone subject, but lovely due to its very good execution. perfect focus, centered comp works well in the square crop, border is just subtle enough. yellows are a tad oversaturated and produce slight banding. bumping up to 8', '2008-07-15 06:46:26.000000', NULL, 1),
(4825682, 698304, 49109, '<td valign="top">good pose and expression, good b/w tones, lighting is a bit harsh, too dark upon her head</td>', 'good pose and expression, good b/w tones, lighting is a bit harsh, too dark upon her head', '2008-07-15 06:47:33.000000', NULL, 1),
(4825684, 698280, 49109, '<td valign="top">nice idea, her expression is not convincing, though. the garden might not have been the best choice for a location (who would stand there reading?). A less colorful shirt would have been less distracting</td>', 'nice idea, her expression is not convincing, though. the garden might not have been the best choice for a location (who would stand there reading?). A less colorful shirt would have been less distracting', '2008-07-15 06:49:27.000000', NULL, 1),
(4825685, 697418, 49109, '<td valign="top">overall too soft, composition is rather uninteresting - had cropped closer. title is extremely cliché</td>', 'overall too soft, composition is rather uninteresting - had cropped closer. title is extremely cliché', '2008-07-15 06:51:12.000000', NULL, 1),
(4825686, 698444, 49109, '<td valign="top">nice storytelling image, like the toning. contrast is too high for my taste. had cropped to square or even portrait format, the additional space at the sides doesn''t do much for the image IMO</td>', 'nice storytelling image, like the toning. contrast is too high for my taste. had cropped to square or even portrait format, the additional space at the sides doesn''t do much for the image IMO', '2008-07-15 06:53:51.000000', NULL, 1),
(4825689, 698071, 94239, '<td valign="top">Great shot. But I found the crop at the top of the head a bit distracting. 7</td>', 'Great shot. But I found the crop at the top of the head a bit distracting. 7', '2008-07-15 06:58:43.000000', NULL, 1),
(4825690, 698879, 94239, '<td valign="top">This is a fantastic idea. The colours and the brilliance of the gold are great too. 7</td>', 'This is a fantastic idea. The colours and the brilliance of the gold are great too. 7', '2008-07-15 07:01:42.000000', NULL, 1),
(4825695, 698621, 46097, '<td valign="top">lovely misty look, dreamy mood. Very good lighting and post processing.</td>', 'lovely misty look, dreamy mood. Very good lighting and post processing.', '2008-07-15 07:11:55.000000', NULL, 1),
