(4832571, 698917, 74911, '<td valign="top">Great play with shadows. B&amp;W is perfect for this.</td>', 'Great play with shadows. B&W is perfect for this.', '2008-07-18 14:55:58.000000', NULL, 1),
(4832575, 696422, 74911, '<td valign="top">Top notch macro shot. Great details. Love the background, the leaf and the droplets. Composition cannot get any better than this, I suppose. My favourite here.</td>', 'Top notch macro shot. Great details. Love the background, the leaf and the droplets. Composition cannot get any better than this, I suppose. My favourite here.', '2008-07-18 14:57:55.000000', NULL, 1),
(4832579, 698913, 74911, '<td valign="top">Burst of colors. The background is also colorful and goes very well with the bird''s colors. Excellent sharpness and unbelievable details. <br/> <br/>The thing at the left bottom corner could have been avoided, I think. The saturation is a little too much for my tastes.</td>', 'Burst of colors. The background is also colorful and goes very well with the bird''s colors. Excellent sharpness and unbelievable details.  The thing at the left bottom corner could have been avoided, I think. The saturation is a little too much for my tastes.', '2008-07-18 14:59:52.000000', NULL, 1),
(4832580, 698114, 74911, '<td valign="top">Good composition. The way the two branches matches with the black shades on the bird''s face is nice. Could have been more sharper.</td>', 'Good composition. The way the two branches matches with the black shades on the bird''s face is nice. Could have been more sharper.', '2008-07-18 15:01:03.000000', NULL, 1),
(4832581, 698933, 74911, '<td valign="top">Great macro shot. Unbelievable details. Bokeh on BG is very nice. An ant on the bee and you caught it? This is just great.</td>', 'Great macro shot. Unbelievable details. Bokeh on BG is very nice. An ant on the bee and you caught it? This is just great.', '2008-07-18 15:02:46.000000', NULL, 1),
