(4832584, 698329, 74911, '<td valign="top">The soft focus is good. But the eyes only could have been sharper than this.</td>', 'The soft focus is good. But the eyes only could have been sharper than this.', '2008-07-18 15:04:34.000000', NULL, 1),
(4832585, 698847, 74911, '<td valign="top">Great play with light. Textures are shown nicely. B&amp;W also works here.</td>', 'Great play with light. Textures are shown nicely. B&W also works here.', '2008-07-18 15:04:44.000000', NULL, 1),
(4832586, 698522, 74911, '<td valign="top">A very good use of light. I like the way you have used the sunlight as rimlight.</td>', 'A very good use of light. I like the way you have used the sunlight as rimlight.', '2008-07-18 15:04:59.000000', NULL, 1),
(4832587, 698739, 74911, '<td valign="top">A very strong portrait. I like the expressions and pose of the model. A bit high contrast, but suits the mood of the picture.</td>', 'A very strong portrait. I like the expressions and pose of the model. A bit high contrast, but suits the mood of the picture.', '2008-07-18 15:05:02.000000', NULL, 1),
