INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4834140, 698656, 96490, '<td valign="top">Wow, I love the golden colors of the background and the subject is fantastic. I think some slightly stronger vignetting could have made the jellyfish ''pop'' a little more though. Nice Job.</td>', 'Wow, I love the golden colors of the background and the subject is fantastic. I think some slightly stronger vignetting could have made the jellyfish ''pop'' a little more though. Nice Job.', '2008-07-19 18:09:14.000000', NULL, 1),
(4834148, 696570, 61396, '<td valign="top">I like the 3D effect created by the distant background.</td>', 'I like the 3D effect created by the distant background.', '2008-07-19 18:14:57.000000', NULL, 1),
(4834215, 698163, 37103, '<td valign="top">I love the gorilla in the background, the sepia like tone and the vintage feel of the photo.</td>', 'I love the gorilla in the background, the sepia like tone and the vintage feel of the photo.', '2008-07-19 19:00:21.000000', NULL, 1),
(4834220, 697725, 37103, '<td valign="top">I like the wrinkled hands and the perfect motion blur of the bird. Although the hands look a little over sharpened/contrasty.</td>', 'I like the wrinkled hands and the perfect motion blur of the bird. Although the hands look a little over sharpened/contrasty.', '2008-07-19 19:01:02.000000', NULL, 1),
(4834223, 697960, 37103, '<td valign="top">gorgeous crisp image. I like the centered/square look.</td>', 'gorgeous crisp image. I like the centered/square look.', '2008-07-19 19:02:33.000000', NULL, 1),
(4834224, 698424, 37103, '<td valign="top">This is a nice clear shot, but it looks overexposed/too light.</td>', 'This is a nice clear shot, but it looks overexposed/too light.', '2008-07-19 19:03:34.000000', NULL, 1),
(4834225, 698847, 37103, '<td valign="top">Wow, I love this crisp leaf and the clear veins. Nice job. The curve of the stem adds a lot as well.</td>', 'Wow, I love this crisp leaf and the clear veins. Nice job. The curve of the stem adds a lot as well.', '2008-07-19 19:04:24.000000', NULL, 1),
(4834228, 698593, 37103, '<td valign="top">very fun image. Although it might have been nice to include a little more of her face.</td>', 'very fun image. Although it might have been nice to include a little more of her face.', '2008-07-19 19:04:53.000000', NULL, 1),
(4834233, 698883, 37103, '<td valign="top">I really like this image, but the exposure seems wrong. I think a little more color or contrast would be better. But gorgeous lines/shape.</td>', 'I really like this image, but the exposure seems wrong. I think a little more color or contrast would be better. But gorgeous lines/shape.', '2008-07-19 19:07:06.000000', NULL, 1),
(4834234, 698900, 37103, '<td valign="top">Creepy, but cool image.</td>', 'Creepy, but cool image.', '2008-07-19 19:07:59.000000', NULL, 1),
(4834241, 697654, 37103, '<td valign="top">What a gorgeous little guy. I like the motion of this shot and the shiny coats!</td>', 'What a gorgeous little guy. I like the motion of this shot and the shiny coats!', '2008-07-19 19:09:50.000000', NULL, 1),
(4834253, 696997, 37103, '<td valign="top">These colors are just stunning. The clarify of the butterfly and the soft blur of the flowers is gorgeous.</td>', 'These colors are just stunning. The clarify of the butterfly and the soft blur of the flowers is gorgeous.', '2008-07-19 19:16:22.000000', NULL, 1),
(4834332, 698446, 92859, '<td valign="top">very good picture! the lighting helps contrast to the entire face, but I personally would have made the eyes a little brighter and a little bit more in focus than the back of the head. then the picture would have given a personal effect as though he is looking straight towards someone.</td>', 'very good picture! the lighting helps contrast to the entire face, but I personally would have made the eyes a little brighter and a little bit more in focus than the back of the head. then the picture would have given a personal effect as though he is looking straight towards someone.', '2008-07-19 20:35:09.000000', NULL, 1),
(4834338, 696996, 92859, '<td valign="top">this picture is perfect in my opinion.<br/> <br/>the water pooring off of the face with the eyes gleeming from the sun and the hair adding texture and form makes a PERFECT picture.<br/> <br/>excellent work!</td>', 'this picture is perfect in my opinion. the water pooring off of the face with the eyes gleeming from the sun and the hair adding texture and form makes a PERFECT picture. excellent work!', '2008-07-19 20:38:35.000000', NULL, 1),
(4834345, 698396, 31535, '<td valign="top">It''s advanced editing. I would have cloned out the dirt spots on the pedals.<br/> <br/>Edit: Well don''t I look dumb. I didn''t even read your title the first time around in voting. Obviously those spots are "imperfections." I don''t really like the flower in the upper right as it doesn''t seem to match the other three flowers. Cloning it out could lead to a DQ though. Your main flower is very detailed and sharp and you can really see the texture in the pedals which it great. Having said that, I still might have cloned out the large brown spot on the left :) 7</td>', 'It''s advanced editing. I would have cloned out the dirt spots on the pedals. Edit: Well don''t I look dumb. I didn''t even read your title the first time around in voting. Obviously those spots are "imperfections." I don''t really like the flower in the upper right as it doesn''t seem to match the other three flowers. Cloning it out could lead to a DQ though. Your main flower is very detailed and sharp and you can really see the texture in the pedals which it great. Having said that, I still might have cloned out the large brown spot on the left :) 7', '2008-07-19 20:41:07.000000', NULL, 1),
(4834349, 698886, 92859, '<td valign="top">the foreground of the biker is good, but it''s the background that makes a distraction for the eye. if only the background would have been a little less distracting by making it out of focus, then it would have made the picture ultimatly perfect!<br/> <br/>overall though, excellent idea, but just change the background to make it really pop through.</td>', 'the foreground of the biker is good, but it''s the background that makes a distraction for the eye. if only the background would have been a little less distracting by making it out of focus, then it would have made the picture ultimatly perfect! overall though, excellent idea, but just change the background to make it really pop through.', '2008-07-19 20:41:20.000000', NULL, 1),
(4834352, 697489, 31535, '<td valign="top">This is my favorite image in the challenge. Great lighting, beautiful model, and well composed. This shot has it all. Bumping to a 10</td>', 'This is my favorite image in the challenge. Great lighting, beautiful model, and well composed. This shot has it all. Bumping to a 10', '2008-07-19 20:41:27.000000', NULL, 1),
(4834358, 698475, 31535, '<td valign="top">I was thinking "dreamy" even before I read your title. You could have cloned out her brastrap, but that''s just a nitpick. Edit: Bumping to a 10 and a fav.</td>', 'I was thinking "dreamy" even before I read your title. You could have cloned out her brastrap, but that''s just a nitpick. Edit: Bumping to a 10 and a fav.', '2008-07-19 20:42:34.000000', NULL, 1),
