INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4836394, 697796, 74588, '<td valign="top">the more i see it <br/>the more i like it</td>', 'the more i see it the more i like it', '2008-07-21 05:58:19.000000', NULL, 0),
(4836396, 698671, 74588, '<td valign="top">how could i have missed this beauty</td>', 'how could i have missed this beauty', '2008-07-21 06:00:44.000000', NULL, 0),
(4836406, 698589, 30982, '<td valign="top">Odd, but delightfully so!  You did very well with this shot - congrats!</td>', 'Odd, but delightfully so!  You did very well with this shot - congrats!', '2008-07-21 06:30:32.000000', NULL, 0),
(4836408, 698541, 82749, '<td valign="top">Congrats on the blue.  Great image!</td>', 'Congrats on the blue.  Great image!', '2008-07-21 06:30:58.000000', NULL, 0),
(4836409, 698524, 30982, '<td valign="top">Your 24-105 does much nicer stuff than mine does.  :-)  But yeah, sweet lens.  Now get the 10-22 - it''s a blast!</td>', 'Your 24-105 does much nicer stuff than mine does.  :-)  But yeah, sweet lens.  Now get the 10-22 - it''s a blast!', '2008-07-21 06:31:39.000000', NULL, 0),
(4836411, 698855, 68035, '<td valign="top">Barbara...was this a model or did you process it this way.  Either way it has kind of a nice weird surreal not of this world feel about it.  Great B&amp;W conversion and I like the perspective</td>', 'Barbara...was this a model or did you process it this way.  Either way it has kind of a nice weird surreal not of this world feel about it.  Great B&W conversion and I like the perspective', '2008-07-21 06:38:50.000000', NULL, 0),
(4836414, 698903, 68035, '<td valign="top">Very nice in your face image and I LOVED the processing that you did on it.  You have created a wonderful 3d effect.  Uber cool</td>', 'Very nice in your face image and I LOVED the processing that you did on it.  You have created a wonderful 3d effect.  Uber cool', '2008-07-21 06:42:01.000000', NULL, 0),
(4836415, 698081, 68035, '<td valign="top">Holy kamoly, no body does it better Roz!  Another awesome insect macro.  The clarity and sharpness are incredible and the richness of the colours just divine.  This got a 9 from me in voting so it goes without saying I think this is seriously underrated<br/> <br/>Top job buddy</td>', 'Holy kamoly, no body does it better Roz!  Another awesome insect macro.  The clarity and sharpness are incredible and the richness of the colours just divine.  This got a 9 from me in voting so it goes without saying I think this is seriously underrated Top job buddy', '2008-07-21 06:44:26.000000', NULL, 0),
(4836417, 698779, 68035, '<td valign="top">Karen I thought this was a sublime image, the strength of the green bokeh works really well.  perhaps it could have done - as you say - with a little deeper DOF to get all of the wings as sharp as the bit by the thorax (I actually think with this it could have been the insect picture of the year)<br/> <br/>Great great capture</td>', 'Karen I thought this was a sublime image, the strength of the green bokeh works really well.  perhaps it could have done - as you say - with a little deeper DOF to get all of the wings as sharp as the bit by the thorax (I actually think with this it could have been the insect picture of the year) Great great capture', '2008-07-21 06:47:59.000000', NULL, 0),
(4836419, 698631, 30982, '<td valign="top">That''s it.  I''m selling my copy of that lens.  It simply can''t do this!  It can''t be the photographer - oh, no.  It must be the lens.  (Mostly it''s that I can''t hold it still enough to get shots like this.)  Lovely guy, by the way.  I''m quite fond of amphibians and reptiles and such.</td>', 'That''s it.  I''m selling my copy of that lens.  It simply can''t do this!  It can''t be the photographer - oh, no.  It must be the lens.  (Mostly it''s that I can''t hold it still enough to get shots like this.)  Lovely guy, by the way.  I''m quite fond of amphibians and reptiles and such.', '2008-07-21 06:51:33.000000', NULL, 0),
(4836420, 698671, 68035, '<td valign="top">I really loved the dof here and the way you took something that was way past its ''sell by'' date and made it look beautiful again.  Great sharpness and the tip of the rose looks to be coming out of the screen.  Certainly deserved more recognition than it got</td>', 'I really loved the dof here and the way you took something that was way past its ''sell by'' date and made it look beautiful again.  Great sharpness and the tip of the rose looks to be coming out of the screen.  Certainly deserved more recognition than it got', '2008-07-21 06:52:44.000000', NULL, 0),
(4836421, 698614, 30982, '<td valign="top">It''s lovely around here this time of year, isn''t it?  When all the green turns to gold.  Nicely captured and congrats on another little star thingie for your collection.</td>', 'It''s lovely around here this time of year, isn''t it?  When all the green turns to gold.  Nicely captured and congrats on another little star thingie for your collection.', '2008-07-21 06:52:47.000000', NULL, 0),
(4836425, 698735, 68035, '<td valign="top">Yeah yeah STILL struggling to get to grips with that new lens.  Another of your amazing images I love the moment in time and the sharpness of the image.  The textures are amazing and I feel I could just reach out and touch the fuzziness of the bee''s body (not that I would of course...Me not stoopid)<br/> <br/>You truly are an amazing artist</td>', 'Yeah yeah STILL struggling to get to grips with that new lens.  Another of your amazing images I love the moment in time and the sharpness of the image.  The textures are amazing and I feel I could just reach out and touch the fuzziness of the bee''s body (not that I would of course...Me not stoopid) You truly are an amazing artist', '2008-07-21 06:59:08.000000', NULL, 0),
(4836427, 698913, 67343, '<td valign="top">Congratulations Sis on your PB and great finish. Beautiful image. :)</td>', 'Congratulations Sis on your PB and great finish. Beautiful image. :)', '2008-07-21 07:07:22.000000', NULL, 0),
(4836428, 698541, 67363, '<td valign="top">ongratulation! Everything about this shot is beautiful. Well done!</td>', 'ongratulation! Everything about this shot is beautiful. Well done!', '2008-07-21 07:08:12.000000', NULL, 0),
(4836429, 698444, 72670, '<td valign="top">Unmistakably a Coley. Congrats!</td>', 'Unmistakably a Coley. Congrats!', '2008-07-21 07:13:54.000000', NULL, 0),
(4836434, 698185, 54566, '<td valign="top">for one thing .. u can see the photographer in the eye. and someone pointed a little un-half bindi. m not a member but would have given 6.</td>', 'for one thing .. u can see the photographer in the eye. and someone pointed a little un-half bindi. m not a member but would have given 6.', '2008-07-21 07:42:38.000000', NULL, 0),
(4836438, 698614, 58785, '<td valign="top">Congrats!<br/> <br/>Very sharp and hurts my eyes when I look at it.. I love the pain... Very nice :P</td>', 'Congrats! Very sharp and hurts my eyes when I look at it.. I love the pain... Very nice :P', '2008-07-21 07:46:55.000000', NULL, 0),
(4836439, 698946, 89341, '<td valign="top">I thought the patterns and textures were really cool in this, and I like how the leaf is composed diagonally. I''m not a huge fan of the background colour and the crop on the left and bottom bothers me just a fraction. I think I''d like the bottom two leaves out of the composition (maybe even cut them off!) and include the whole of the leaf that''s tip is just out of the shot.</td>', 'I thought the patterns and textures were really cool in this, and I like how the leaf is composed diagonally. I''m not a huge fan of the background colour and the crop on the left and bottom bothers me just a fraction. I think I''d like the bottom two leaves out of the composition (maybe even cut them off!) and include the whole of the leaf that''s tip is just out of the shot.', '2008-07-21 07:49:29.000000', NULL, 0),
(4836443, 698866, 89341, '<td valign="top">I don''t photograph people so feel free to disregard this as I probably don''t know what I''m talking about :) but ... I like the head tilt and the sharpness and brightness of her eyes are great and really draws me into the photo ... I think the fence is a little distracting for me, the colour is a little to similar(ish) to her hair and face, maybe the green background all over would work better. Also on the right there seems to be some hair from somewhere else (another person?) which catches my eye and drags it out of the photo</td>', 'I don''t photograph people so feel free to disregard this as I probably don''t know what I''m talking about :) but ... I like the head tilt and the sharpness and brightness of her eyes are great and really draws me into the photo ... I think the fence is a little distracting for me, the colour is a little to similar(ish) to her hair and face, maybe the green background all over would work better. Also on the right there seems to be some hair from somewhere else (another person?) which catches my eye and drags it out of the photo', '2008-07-21 07:54:38.000000', NULL, 0),
(4836445, 698819, 89341, '<td valign="top">This is cool and is a great abstract shot, I really like it. I love the colours, the negative space and the composition. I think I would like to see something a little sharper on the marble maybe, though that could just be how the marble is! Colours are a little saturated but I like that as the black balances it out.</td>', 'This is cool and is a great abstract shot, I really like it. I love the colours, the negative space and the composition. I think I would like to see something a little sharper on the marble maybe, though that could just be how the marble is! Colours are a little saturated but I like that as the black balances it out.', '2008-07-21 07:57:48.000000', NULL, 0),
(4836446, 696422, 91716, '<td valign="top">Very beautiful</td>', 'Very beautiful', '2008-07-21 07:58:18.000000', NULL, 0),
(4836447, 698741, 52549, '<td valign="top">Congrats on top 10, Cindi. Wonderful shot.</td>', 'Congrats on top 10, Cindi. Wonderful shot.', '2008-07-21 08:01:29.000000', NULL, 0),
(4836448, 698260, 89341, '<td valign="top">I think this is a cool idea, I love the set up. I also like the plain white background. I think maybe though there is a little too much in the shot, personally I would have removed the middle tower and positioned the tower on the left in the middle and raised it so it wasn''t behind either of the dragons and then have a tighter crop. A little shadow / highlights and increasing the saturation just a little would help the dragons stand out more as well.</td>', 'I think this is a cool idea, I love the set up. I also like the plain white background. I think maybe though there is a little too much in the shot, personally I would have removed the middle tower and positioned the tower on the left in the middle and raised it so it wasn''t behind either of the dragons and then have a tighter crop. A little shadow / highlights and increasing the saturation just a little would help the dragons stand out more as well.', '2008-07-21 08:02:55.000000', NULL, 0),
(4836449, 697489, 52549, '<td valign="top">Wonderful portrait. Congrats on top 10, Leo.</td>', 'Wonderful portrait. Congrats on top 10, Leo.', '2008-07-21 08:03:46.000000', NULL, 0),
(4836450, 698782, 89341, '<td valign="top">Yikes! This is a great close up, the detail is really good and the background colour works well for me. It does have a bit of an Ick factor so perhaps that was what put people off!</td>', 'Yikes! This is a great close up, the detail is really good and the background colour works well for me. It does have a bit of an Ick factor so perhaps that was what put people off!', '2008-07-21 08:04:37.000000', NULL, 0),
