INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4840711, 698836, 3724, '<td valign="top">Great kitty foto -  I love this soft process and idea. <br/><a href="//www.whizkidtech.redprince.net/zoneplate/" rel="nofollow" target="_blank">Zone Plate Designer</a> <br/>A "zoneplate/pinhole challenge" would be great fun.</td>', 'Great kitty foto -  I love this soft process and idea. Zone Plate Designer A "zoneplate/pinhole challenge" would be great fun.', '2008-07-23 10:14:25.000000', NULL, 0),
(4840713, 698854, 30982, '<td valign="top">Lovely capture with the deer right where it needed to be in the light.  Well composed, and I like the bit of brown just above the deer - seems perfectly placed there!</td>', 'Lovely capture with the deer right where it needed to be in the light.  Well composed, and I like the bit of brown just above the deer - seems perfectly placed there!', '2008-07-23 10:17:49.000000', NULL, 0),
(4840714, 698766, 30982, '<td valign="top">What a nifty find!  I like Germaine''s comment about a new take on still life.  And very nice handling of the HDR - quite subtle and not obviously HDR, which is good.</td>', 'What a nifty find!  I like Germaine''s comment about a new take on still life.  And very nice handling of the HDR - quite subtle and not obviously HDR, which is good.', '2008-07-23 10:19:26.000000', NULL, 0),
(4840715, 698866, 30982, '<td valign="top">Heh!  Yes she would!  Lovely natural portrait, both the light and the smile.  Very real, very nice!</td>', 'Heh!  Yes she would!  Lovely natural portrait, both the light and the smile.  Very real, very nice!', '2008-07-23 10:20:10.000000', NULL, 0),
(4840717, 698869, 30982, '<td valign="top">And here I thought you pasted the plant to the bulb, but was trying to figure out how it looked so natural that way.  Lovely, and it appears to have been very well appreciated, too.</td>', 'And here I thought you pasted the plant to the bulb, but was trying to figure out how it looked so natural that way.  Lovely, and it appears to have been very well appreciated, too.', '2008-07-23 10:21:25.000000', NULL, 0),
(4840719, 698855, 30982, '<td valign="top">Very realistic indeed!  I like the very natural feel of it.</td>', 'Very realistic indeed!  I like the very natural feel of it.', '2008-07-23 10:22:17.000000', NULL, 0),
(4840720, 698671, 30982, '<td valign="top">More nifty hardware to add to your profile page, which is becoming way more colorful and interesting than those of the mega-ribbon winners.  You really do know how to reach an audience - I stand in awe!!</td>', 'More nifty hardware to add to your profile page, which is becoming way more colorful and interesting than those of the mega-ribbon winners.  You really do know how to reach an audience - I stand in awe!!', '2008-07-23 10:23:23.000000', NULL, 0),
(4840724, 698866, 3724, '<td valign="top">Subject Alice comfortable in front of your lens. I like the tilt of her head. Beautiful portrait. 7</td>', 'Subject Alice comfortable in front of your lens. I like the tilt of her head. Beautiful portrait. 7', '2008-07-23 10:25:39.000000', NULL, 0),
(4840739, 698274, 30982, '<td valign="top">He''s very well camoflauged!  Not sure if I''d have hit this with a bit more bright/levels or not - it''s a bit on the darkish side on my monitor, but my monitor runs a bit on the darkish side.</td>', 'He''s very well camoflauged!  Not sure if I''d have hit this with a bit more bright/levels or not - it''s a bit on the darkish side on my monitor, but my monitor runs a bit on the darkish side.', '2008-07-23 10:41:05.000000', NULL, 0),
(4840744, 698623, 30982, '<td valign="top">What I liked about this was the fact the reflection was the subject, not the view beyond.  A nifty upside downish perspective that in my opinion worked pretty darn well!</td>', 'What I liked about this was the fact the reflection was the subject, not the view beyond.  A nifty upside downish perspective that in my opinion worked pretty darn well!', '2008-07-23 10:42:20.000000', NULL, 0),
(4840749, 698665, 30982, '<td valign="top">This is one helluva cool macro.  The part I liked best (of course the detail in the fly is awesome) is the shadow.</td>', 'This is one helluva cool macro.  The part I liked best (of course the detail in the fly is awesome) is the shadow.', '2008-07-23 10:43:50.000000', NULL, 0),
(4840752, 698625, 30982, '<td valign="top">Very crisp detail, good composition, and a well presented sentiment.</td>', 'Very crisp detail, good composition, and a well presented sentiment.', '2008-07-23 10:44:28.000000', NULL, 0),
(4840772, 696422, 20441, '<td valign="top"><b></b>super shot; you have many more ribbons in your future</td>', 'super shot; you have many more ribbons in your future', '2008-07-23 10:55:16.000000', NULL, 0),
(4841031, 697954, 66384, '<td valign="top">I like the desat. I think what it is lacking is contrast. As Kashi said the attention goes to the bike part in the lower right. That seems to have the sharpest focus and the most contrast. I''d like to see more contrast in the eyes and smile with sharper focus there. Perhaps a High Pass layer with a mask would do it. I like the square crop and the composition, and the joy of a boy with his bike.</td>', 'I like the desat. I think what it is lacking is contrast. As Kashi said the attention goes to the bike part in the lower right. That seems to have the sharpest focus and the most contrast. I''d like to see more contrast in the eyes and smile with sharper focus there. Perhaps a High Pass layer with a mask would do it. I like the square crop and the composition, and the joy of a boy with his bike.', '2008-07-23 13:32:18.000000', NULL, 0),
(4841039, 698524, 66384, '<td valign="top">Beautiful composition and DOF. I love the fountain bokeh and the sharp focus on the old man. He looks like he is going to make a wish, which is so poignant for a man of his age. Congratulation on your new top row entry.</td>', 'Beautiful composition and DOF. I love the fountain bokeh and the sharp focus on the old man. He looks like he is going to make a wish, which is so poignant for a man of his age. Congratulation on your new top row entry.', '2008-07-23 13:37:27.000000', NULL, 0),
(4841044, 698685, 66384, '<td valign="top">Thanks for the recipe. The image is stunning -- particularly the light on the ceiling. I also really like the little sunlight crosses on the pavement and the tritone finish.</td>', 'Thanks for the recipe. The image is stunning -- particularly the light on the ceiling. I also really like the little sunlight crosses on the pavement and the tritone finish.', '2008-07-23 13:43:38.000000', NULL, 0),
(4841131, 698819, 3936, '<td valign="top">Critique Club Review:<br/> <br/>Color Saturation and Hue:  Colors are very saturated in this image, but work well here.  <br/> <br/>Brightness and contrast:  The white area at the top of the marble has reached burn out and is a little bit distracting.  A little darker background might be good also.  There is a faint out of focus area that shows up to the left of the marble.  Were it gone, it could help the image.<br/> <br/>Focus and depth of field:  Focus is good, but depth of field feels a little bit short.  The softness at the edges of the marble become pronunced at the top, due to all the color and brightness there.  If the whole marble were sharper, I''d like it better.<br/> <br/>Overall:  I like this image alot.  Feels sort of like stained glass.  Keeping the LEDs in soft focus was a nice touch.<br/> <br/></td>', 'Critique Club Review: Color Saturation and Hue:  Colors are very saturated in this image, but work well here.   Brightness and contrast:  The white area at the top of the marble has reached burn out and is a little bit distracting.  A little darker background might be good also.  There is a faint out of focus area that shows up to the left of the marble.  Were it gone, it could help the image. Focus and depth of field:  Focus is good, but depth of field feels a little bit short.  The softness at the edges of the marble become pronunced at the top, due to all the color and brightness there.  If the whole marble were sharper, I''d like it better. Overall:  I like this image alot.  Feels sort of like stained glass.  Keeping the LEDs in soft focus was a nice touch. ', '2008-07-23 14:40:58.000000', NULL, 0),
